<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>履约核查</h2><p>与商户维护的是同一份方式、固定费用与点位事实。平台只读核查。</p></div></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data"/><div class="ui-search"><label>商户<BusinessSelect v-model="targetStore" type="stores" @input="clear"/></label><label>点位类型<Select v-model="type" clearable><Option value="COMMUNITY_PICKUP">社区自提</Option><Option value="STORE_REDEMPTION">到店核销</Option></Select></label><label>点位启停<Select v-model="enabled" clearable><Option value="true">启用</Option><Option value="false">停用</Option></Select></label><div class="ui-actions"><Button type="primary" :disabled="!targetStore" @click="page=1;reload()">核查</Button><Button @click="reset">重置</Button></div></div><p v-if="!targetStore" class="ui-empty">请选择商户开始核查，无需复制Store编号。</p><template v-if="selected"><DetailSection title="四种履约方式" :grid="false"><Table class="s1-list-table" v-compact-table :data="methodRows" :columns="methodColumns"><template slot="state" slot-scope="{row}"><Tag :color="row.enabled?'green':'default'">{{row.enabled?'配置启用':'配置停用'}}</Tag><Tag :color="row.effective?'green':'orange'">{{row.effective?'当前有效':'当前无效'}}</Tag></template><template slot="fee" slot-scope="{row}">{{money(row.feeCent)}}<span class="ui-meta">{{row.delivery?'每个Store Order固定一次':'自提／核销免费'}}</span></template><template slot="scope" slot-scope="{row}">{{row.scope}}</template></Table><p class="ui-note">配置启用不保证当前有效；店铺关闭或最后一个有效点位失效时，相应方式仍不可用于新业务。</p></DetailSection><DetailSection title="自提点与核销点" :grid="false"><Table class="s1-list-table" v-compact-table :data="records" :columns="pointColumns" :loading="loading" no-data-text="没有符合条件的点位"><template slot="type" slot-scope="{row}">{{status(row.type)}}</template><template slot="state" slot-scope="{row}"><Tag :color="row.enabled?'green':'default'">{{row.enabled?'启用':'停用'}}</Tag><span class="ui-meta">{{row.complete?'资料完整':'待补资料'}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="openPoint(row)">详情与历史</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/></DetailSection><DetailSection title="履约配置历史" :grid="false"><Table class="s1-list-table" v-compact-table :data="selected.history" :columns="historyColumns"><template slot="time" slot-scope="{row}">{{date(row.at)}}</template><template slot="methods" slot-scope="{row}"><span v-for="(name,key) in methods" :key="key" class="ui-two-line">{{name}}：{{row.methods[key]&&row.methods[key].enabled?'启用':'停用'}}；{{money(row.methods[key]&&row.methods[key].feeCent)}}</span></template></Table></DetailSection></template><Drawer v-model="showPoint" title="点位核查与历史" width="85" @on-close="closePoint"><div v-if="point" class="s1-ui"><header class="ui-header"><div><h2>{{point.name}}</h2><p class="ui-meta">编号 {{point.id}} · v{{point.version}}</p></div></header><Tabs :animated="false"><TabPane label="当前资料" name="current"><PointFields :point="point"/></TabPane><TabPane label="历史版本" name="history"><Select v-model="historyVersion" style="max-width:280px"><Option v-for="h in pointHistory" :key="h.version" :value="String(h.version)">版本 {{h.version}} · {{date(h.at)}}</Option></Select><Alert v-if="historicalPoint" show-icon>只读历史版本。</Alert><PointFields v-if="historicalPoint" :point="historicalPoint"/></TabPane></Tabs></div><p v-if="pointError" class="s1-ui ui-error">{{pointError}}</p></Drawer></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import BusinessSelect from './components/BusinessSelect';import DetailSection from './components/DetailSection';import PointFields from './components/PointFields';export default {mixins:[page],components:{PageStatus,BusinessSelect,DetailSection,PointFields},data:()=>({targetStore:'',type:'',enabled:'',regionNames:{},showPoint:false,point:null,pointHistory:[],historyVersion:'',pointError:'',pointTicket:0,methodColumns:[{title:'方式',key:'name',width:140},{title:'启用／实际有效',slot:'state',minWidth:190},{title:'固定费用',slot:'fee',minWidth:185},{title:'范围／说明',slot:'scope',minWidth:260}],pointColumns:[{title:'点位名称',key:'name',minWidth:160},{title:'类型',slot:'type',width:120},{title:'状态',slot:'state',minWidth:120},{title:'地址',key:'address',minWidth:220},{title:'联系人',key:'contactName',width:120},{title:'操作',slot:'operations',width:140}],historyColumns:[{title:'版本',key:'version',width:80},{title:'方式与固定费',slot:'methods',minWidth:290},{title:'原因',key:'reason',minWidth:200},{title:'时间',slot:'time',minWidth:190}]}),computed:{methodRows(){const cfg=this.selected&&this.selected.methods||{};return Object.entries(this.methods).map(([key,name])=>{const value=cfg[key]||{},delivery=['MERCHANT_DELIVERY','EXPRESS'].includes(key),codes=value.nationwide?value.excludedDistrictCodes||[]:value.districtCodes||[];return {key,name,enabled:value.enabled===true,effective:(this.selected.effectiveMethods||[]).includes(key),delivery,feeCent:value.feeCent,scope:delivery?(value.nationwide?'全国；排除：':'配送区县：')+(codes.map(c=>this.regionNames[c]||'名称未提供（'+c+'）').join('、')||'未配置')+(value.description?'；'+value.description:''):'本Store同类型全部有效点位；'+(value.description||'无补充说明')};});},historicalPoint(){const h=this.pointHistory.find(h=>String(h.version)===this.historyVersion);return h&&h.snapshot;}},watch:{'$route.query.targetStore'(value){this.targetStore=value||'';this.clear();if(value)this.reload();}},mounted(){this.targetStore=this.$route.query.targetStore||(this.demoActive?this.demoStore:'');if(this.targetStore)this.reload();},beforeDestroy(){this.pointTicket++;},methods:{clear(){this.ticket++;this.selected=null;this.records=[];this.total=0;this.error='';this.loading=false;this.closePoint();},reset(){this.targetStore='';this.type='';this.enabled='';this.clear();},reload(){if(!this.targetStore)return;const store=this.targetStore;return this.latest(async()=>{const [configuration,points]=await Promise.all([this.read('/stores/'+store+'/fulfillment'),this.read('/stores/'+store+'/points',{type:this.type||undefined,enabled:this.enabled||undefined,pageNumber:this.page,pageSize:this.size})]);const codes=[...new Set(Object.values(configuration.methods||{}).flatMap(m=>[...(m.districtCodes||[]),...(m.excludedDistrictCodes||[])]))],names={};for(let i=0;i<codes.length;i+=200){const rows=await this.ui('/region-names',{codes:codes.slice(i,i+200).join(',')});rows.forEach(r=>{names[r.code]=[r.provinceName,r.cityName,r.name].filter(Boolean).join(' / ');});}return {configuration,points,names};},v=>{this.selected=v.configuration;this.records=v.points.records;this.total=v.points.total;this.regionNames=v.names;},()=>{this.selected=null;this.records=[];this.regionNames={};});},async openPoint(row){const store=this.targetStore,id=row.id,ticket=++this.pointTicket;this.point=null;this.pointHistory=[];this.pointError='';this.showPoint=true;try{const value=await this.ui('/stores/'+store+'/point',{pointId:id});if(ticket===this.pointTicket&&store===this.targetStore){this.point=value.point;this.pointHistory=value.history;this.historyVersion=value.history.length?String(value.history[0].version):'';}}catch(e){if(ticket===this.pointTicket)this.pointError=e.message;}},closePoint(){this.pointTicket++;this.showPoint=false;this.point=null;this.pointHistory=[];}}};</script>
